import{z as n,x as B,o as E,c as o,q as r,j as d,D as t,d as e,s as A,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"GAE 与 λ","description":"","frontmatter":{"title":"GAE 与 λ","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/gae-lambda.md","filePath":"llm/gae-lambda.md","lastUpdated":1791413859000}'),s={name:"llm/gae-lambda.md"};function p(b,a,_,h,D,c){const m=B("Mermaid");return E(),o("div",null,[a[2]||(a[2]=r('<h1 id="gae-与-λ" tabindex="-1">GAE 与 λ <a class="header-anchor" href="#gae-与-λ" aria-label="Permalink to &quot;GAE 与 λ&quot;">​</a></h1><div class="epigraph"><p>λ 在一步 TD 与整条蒙特卡洛之间插值：语言模型的地平线很长，这个旋钮决定中间 token 能不能分到终点的对错。</p><footer>—— Schulman 等，High-Dimensional Continuous Control Using Generalized Advantage Estimation, ICLR 2016</footer></div><p><a href="/llm/token-level-reward">上一课</a>给出逐步 \\(r_t\\) 与终点 \\(R\\)。接到 <a href="/llm/ppo-llm">PPO</a> 时，还要把它们收成优势 \\(\\hat A_t\\)。缺口是：<strong>纯蒙特卡洛方差太大，纯 TD 又依赖不准的 critic。</strong> Schulman 的 GAE 用 \\(\\lambda\\) 做偏差–方差插值。本课只写 \\(\\lambda\\) 在 LLM 上的含义，不重推 PPO clip。<a href="/llm/grpo">GRPO</a> 没有 critic，也就没有 GAE；对照写明。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>定义 TD 残差 \\(\\delta_t = r_t + \\gamma V(s_{t+1}) - V(s_t)\\)。\\(\\lambda=0\\) 时 \\(\\hat A_t=\\delta_t\\)，完全信 critic；\\(\\lambda=1\\) 时 \\(\\hat A_t\\) 回到折扣回报减 \\(V(s_t)\\)，完全信采样回报。LLM 的 \\(T\\) 大、\\(r_t\\) 稀疏，两端都难受：\\(\\lambda=0\\) 则早期步只看见塑形项；\\(\\lambda=1\\) 则一条长链的噪声抹过所有 token。需要中间值，并且 \\(\\gamma\\) 常取 \\(1\\)（有限长度、不贴现），于是 \\(\\lambda\\) 几乎是唯一插值。</p><p>InstructGPT / 常见 LLM-PPO 配方把 GAE 当默认。缺 \\(\\lambda\\) 的复现表等于没给优势定义。</p><p><span class="marginnote">TD 残差 \\(\\delta_t\\) 翻译成大白话：这一步实际拿到手的（当场奖励 \\(r_t\\) 加下一步的估价 \\(V(s_{t+1})\\)）比 critic 事前估的 \\(V(s_t)\\) 好多少。正数是超预期，负数是不及预期——它是 GAE 的最小积木，后面的一切混合都从它出发。</span></p><h3 id="时-λ-仍有意义" tabindex="-1">\\(\\gamma=1\\) 时 λ 仍有意义 <a class="header-anchor" href="#时-λ-仍有意义" aria-label="Permalink to &quot;$\\gamma=1$ 时 λ 仍有意义&quot;">​</a></h3><p>不贴现不等于蒙特卡洛。\\(\\lambda\\) 控制的是「向后看多少步 critic 误差」。\\(\\gamma=1,\\lambda=1\\) 才是满地平线回报。有人把 \\(\\gamma\\) 设成 \\(0.99\\) 再配短 \\(\\lambda\\)，等于故意让远期校验器对开头几乎无影响——若任务是整题对错，这通常是错的。</p><p><span class="marginnote">优势归一化（batch 内减均值除标准差）在 GAE 之后做，改变尺度不改变 \\(\\lambda\\) 的相对混合。两者不要互相代替。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2> \\[\\hat A_t^{\\mathrm{GAE}(\\gamma,\\lambda)}=\\sum_{l=0}^{T-t-1}(\\gamma\\lambda)^l \\delta_{t+l}. \\]<p>实现：从后往前递推，padding 位 mask。价值 \\(V\\) 只在真实 token 上回归 \\(\\hat A_t+V_{\\mathrm{old}}\\) 或 \\(\\delta\\) 目标。\\(\\lambda\\) 常见 \\(0.95\\)–\\(0.99\\)；长链推理可偏大，让终点 \\(R\\) 传得更远。没有逐步 \\(r_t\\) 时，\\(r_t=0\\)（除终点与逐步 KL 外），\\(\\lambda\\) 更要偏大，否则中间全是零优势。</p>',13)),(E(),d(i,null,{default:t(()=>[A(m,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20RT%5B%22%E9%80%90%E6%AD%A5%20r_t%22%5D%20--%3E%20D%5B%22TD%20%E6%AE%8B%E5%B7%AE%20%CE%B4_t%22%5D%0A%20%20V%5B%22%E4%BB%B7%E5%80%BC%20V%22%5D%20--%3E%20D%0A%20%20D%20--%3E%20GAE%5B%22%CE%BB%20%E6%B7%B7%E5%90%88%E5%BE%97%20A%CC%82%22%5D%0A%20%20GAE%20--%3E%20CLIP%5B%22PPO%20%E8%A3%81%E5%89%AA%E7%9B%AE%E6%A0%87%22%5D%0A%20%20GAE%20--%3E%20VL%5B%22%E4%BB%B7%E5%80%BC%E5%9B%9E%E5%BD%92%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,"GRPO / RLOO 用组内标量优势，相当于每条轨迹一个 \\(\\hat A\\)，再广播到 token，没有 \\(\\lambda\\)。若要逐步信用，回到 PPO+GAE，或给 GRPO 显式 \\(r_t\\)（上一课）。不要把「GRPO 的组标准差」叫做 \\(\\lambda\\)。",-1)),a[4]||(a[4]=l("p",null,[l("span",{class:"marginnote"},"给个数字感受 \\(\\lambda\\) 的衰减速度：\\(\\lambda=0.95\\) 时，10 步以外的残差权重还剩 \\(0.95^{10}\\approx 0.60\\)，60 步外只剩 \\(0.95^{60}\\approx 0.05\\)。想让千 token 之外的终点对错稳稳传到句首，就得让 \\(\\lambda\\) 逼近 1——这正是长链推理配方偏大的原因。")],-1)),a[5]||(a[5]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=l("p",null,"\\(\\lambda\\) 减小，优势更局部，对错误 \\(V\\) 更不敏感，但终点对错传不到选题策略的前几个 token。\\(\\lambda\\) 增大，长程依赖进来，方差增大，需要更大 batch 或更强归一化。这与控制里的经验相同，只是 LLM 的「长程」是语义决策而不是关节力矩。",-1)),a[7]||(a[7]=l("p",null,"价值函数差时，高 \\(\\lambda\\) 更安全（少信 \\(V\\)）；价值好时，可降 \\(\\lambda\\) 降方差。LLM 上 \\(V\\) 往往差，因此配方偏高 \\(\\lambda\\)。下一课 clip-higher 改的是策略更新幅度，与 GAE 正交，不要用 clip 去补 \\(\\lambda\\) 选错。",-1)),(E(),d(i,null,{default:t(()=>[A(m,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%7B%22%CE%BB%20%E6%8B%A7%E5%9C%A8%E5%93%AA%E4%B8%80%E6%A1%A3%EF%BC%9F%22%7D%0A%20%20K%20--%3E%7C%22%CE%BB%20%3D%200%22%7C%20Z%5B%22%E5%8F%AA%E4%BF%A1%20%CE%B4_t%EF%BC%9Acritic%20%E8%AF%B4%E4%BA%86%E7%AE%97%22%5D%0A%20%20Z%20--%3E%20Z2%5B%22%E6%96%B9%E5%B7%AE%E5%B0%8F%EF%BC%8C%E4%BD%86%E7%BB%88%E7%82%B9%E5%AF%B9%E9%94%99%E4%BC%A0%E4%B8%8D%E5%88%B0%E6%97%A9%E6%9C%9F%20token%22%5D%0A%20%20K%20--%3E%7C%22%CE%BB%20%E2%89%88%200.95%22%7C%20M%5B%22%E5%87%A0%E6%AD%A5%E5%86%85%E7%9A%84%E6%AE%8B%E5%B7%AE%E5%8A%A0%E6%9D%83%E6%B7%B7%E5%90%88%22%5D%0A%20%20M%20--%3E%20M2%5B%22%E5%81%8F%E5%B7%AE%E4%B8%8E%E6%96%B9%E5%B7%AE%E6%8A%98%E4%B8%AD%EF%BC%8CLLM%20%E5%B8%B8%E7%94%A8%E6%A1%A3%E4%BD%8D%22%5D%0A%20%20K%20--%3E%7C%22%CE%BB%20%3D%201%22%7C%20O%5B%22%E6%95%B4%E6%9D%A1%E5%9B%9E%E6%8A%A5%EF%BC%9A%E9%87%87%E6%A0%B7%E8%AF%B4%E4%BA%86%E7%AE%97%22%5D%0A%20%20O%20--%3E%20O2%5B%22%E7%BB%88%E7%82%B9%E4%BF%A1%E5%8F%B7%E5%85%A8%E7%A8%8B%E5%8F%AF%E8%BE%BE%EF%BC%8C%E9%95%BF%E9%93%BE%E5%99%AA%E5%A3%B0%E4%B9%9F%E5%85%A8%E8%BF%9B%E6%9D%A5%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">这一步做错的典型后果：把 \\(\\lambda\\) 当折扣因子、跟着 \\(\\gamma\\) 一起调小，终点奖励几乎传不到开头几个 token，模型只能学到「别提前收尾」之类的局部噪声，整段回答该往哪个方向改就丢了。\\(\\gamma\\) 管「要不要远期」，\\(\\lambda\\) 管「信 critic 几步」，是两个旋钮。</span></p><p><span class="marginnote">\\(\\lambda=1\\) 且无 \\(V\\)（减组均值）就是带基线的蒙特卡洛，接近 REINFORCE / GRPO 精神。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有 critic 就不要假装 GAE。异步 rollout 下 \\(V\\) 与生成策略版本不一致，\\(\\delta_t\\) 系统偏，应降低对 \\(V\\) 的信任（提高 \\(\\lambda\\)）或重算 \\(V\\)。价值初始化见后课。\\(\\lambda\\) 与逐步 KL 的 \\(\\beta\\) 耦合：KL 已很密时，即使 \\(\\lambda\\) 小，中间也有信号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GAE 用 \\(\\lambda\\) 在 TD 与蒙特卡洛之间插值；LLM 地平线长，\\(\\lambda\\) 决定终点能否传到早期 token。</li><li>\\(\\gamma=1\\) 常见；真正的满回报还要 \\(\\lambda=1\\)。</li><li>GRPO 无 GAE；组优势不是 \\(\\lambda\\)。</li><li>\\(V\\) 差时偏高 \\(\\lambda\\)。</li><li>出处：Schulman 等 GAE, ICLR 2016；LLM 用法见 Ouyang 等 InstructGPT / PPO 实现。</li></ul>',6))])}const g=n(s,[["render",p]]);export{u as __pageData,g as default};
